.text
_nova_check_rdi:
    test rdi, 1
    jz .ccr_yes
    xor eax, eax
    ret
    test rdi, rdi
    js .ccr_no
    lea rax, [rip + _strlit_start]
    cmp rdi, rax
    jb .ccr_after_strlit
    lea rax, [rip + _strlit_end]
    cmp rdi, rax
    jb .ccr_yes
.ccr_after_strlit:
    mov rax, [rip + _heap_base]
    test rax, rax
    jz .ccr_after_heap
    cmp rdi, rax
    jb .ccr_after_heap
    mov rax, [rip + _heap_end]
    cmp rdi, rax
    jb .ccr_yes
.ccr_after_heap:
    mov rax, 0x400000000
    cmp rdi, rax
    jae .ccr_yes
.ccr_no:
    xor eax, eax
    ret
.ccr_yes:
    mov eax, 1
    test eax, eax
    ret

_nova_check_rsi:
    test rsi, 1
    jz .ccs_yes
    xor eax, eax
    ret
    test rsi, rsi
    js .ccs_no
    lea rax, [rip + _strlit_start]
    cmp rsi, rax
    jb .ccs_after_strlit
    lea rax, [rip + _strlit_end]
    cmp rsi, rax
    jb .ccs_yes
.ccs_after_strlit:
    mov rax, [rip + _heap_base]
    test rax, rax
    jz .ccs_after_heap
    cmp rsi, rax
    jb .ccs_after_heap
    mov rax, [rip + _heap_end]
    cmp rsi, rax
    jb .ccs_yes
.ccs_after_heap:
    mov rax, 0x400000000
    cmp rsi, rax
    jae .ccs_yes
.ccs_no:
    xor eax, eax
    ret
.ccs_yes:
    mov eax, 1
    test eax, eax
    ret

_nova_add:
    call _nova_check_rdi
    jz .add_int
    call _nova_check_rsi
    jz .add_int
    jmp _nova_concat
.add_int:
    lea rax, [rdi + rsi]
    dec rax
    ret

_nova_mul:
    call _nova_check_rdi
    jnz .mul_ptr
    call _nova_check_rsi
    jnz .mul_ptr_swap
    lea rax, [rdi - 1]
    mov rcx, rsi
    sar rcx, 1
    imul rax, rcx
    inc rax
    ret
.mul_ptr_swap:
    xchg rdi, rsi
.mul_ptr:
    cmp qword ptr [rdi], -1
    je .mul_list
    push rbp
    mov rbp, rsp
    call str_repeat
    pop rbp
    ret
.mul_list:
    push rbp
    mov rbp, rsp
    call _nova_list_repeat
    pop rbp
    ret

_nova_pow:
    mov rax, 1
    test rsi, rsi
    jz .pow_done
.pow_loop:
    imul rax, rdi
    dec rsi
    jnz .pow_loop
.pow_done:
    ret

_nova_list_repeat:
    push rbp
    mov rbp, rsp
    push r12
    push r13
    push r14
    push r15
    mov r12, rdi
    mov r13, rsi
    sar r13, 1
    call _nova_list_new
    mov r14, rax
    xor r15, r15
.listrep_outer:
    cmp r15, r13
    jge .listrep_done
    mov rax, [r12 + 8]
    xor rcx, rcx
.listrep_inner:
    cmp rcx, rax
    jge .listrep_next
    push rax
    push rcx
    mov rdx, [r12 + 24]
    mov rsi, [rdx + rcx*8]
    mov rdi, r14
    call _nova_push
    pop rcx
    pop rax
    inc rcx
    jmp .listrep_inner
.listrep_next:
    inc r15
    jmp .listrep_outer
.listrep_done:
    mov rax, r14
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    ret

_nova_eq:
    cmp rdi, rsi
    je .eq_true
    call _nova_check_rdi
    jz .eq_false
    call _nova_check_rsi
    jz .eq_false
    push rbp
    mov rbp, rsp
    call _nova_str_eq
    lea rax, [rax + rax + 1]
    pop rbp
    ret
.eq_true:
    mov eax, 3
    ret
.eq_false:
    mov eax, 1
    ret

_nova_neq:
    cmp rdi, rsi
    je .neq_false
    call _nova_check_rdi
    jz .neq_true
    call _nova_check_rsi
    jz .neq_true
    push rbp
    mov rbp, rsp
    call _nova_str_eq
    xor eax, 1
    lea rax, [rax + rax + 1]
    pop rbp
    ret
.neq_true:
    mov eax, 3
    ret
.neq_false:
    mov eax, 1
    ret

_nova_lt:
    call _nova_check_rdi
    jz .lt_int
    call _nova_check_rsi
    jz .lt_int
    push rbp
    mov rbp, rsp
    call _nova_strcmp
    pop rbp
    test rax, rax
    setl al
    movzx rax, al
    ret
.lt_int:
    cmp rdi, rsi
    setl al
    movzx rax, al
    ret

_nova_gt:
    call _nova_check_rdi
    jz .gt_int
    call _nova_check_rsi
    jz .gt_int
    push rbp
    mov rbp, rsp
    call _nova_strcmp
    pop rbp
    test rax, rax
    setg al
    movzx rax, al
    ret
.gt_int:
    cmp rdi, rsi
    setg al
    movzx rax, al
    ret

_nova_le:
    call _nova_check_rdi
    jz .le_int
    call _nova_check_rsi
    jz .le_int
    push rbp
    mov rbp, rsp
    call _nova_strcmp
    pop rbp
    test rax, rax
    setle al
    movzx rax, al
    ret
.le_int:
    cmp rdi, rsi
    setle al
    movzx rax, al
    ret

_nova_ge:
    call _nova_check_rdi
    jz .ge_int
    call _nova_check_rsi
    jz .ge_int
    push rbp
    mov rbp, rsp
    call _nova_strcmp
    pop rbp
    test rax, rax
    setge al
    movzx rax, al
    ret
.ge_int:
    cmp rdi, rsi
    setge al
    movzx rax, al
    ret

_nova_strcmp:
    push r12
    push r13
    mov r12, rdi
    mov r13, rsi
.strcmp_loop:
    movzx eax, byte ptr [r12]
    movzx ecx, byte ptr [r13]
    test al, al
    jz .strcmp_end
    test cl, cl
    jz .strcmp_end
    cmp al, cl
    jne .strcmp_diff
    inc r12
    inc r13
    jmp .strcmp_loop
.strcmp_diff:
    sub rax, rcx
    pop r13
    pop r12
    ret
.strcmp_end:
    sub rax, rcx
    pop r13
    pop r12
    ret

_nova_print_int:
    push rbp
    mov rbp, rsp
    sub rsp, 32
    mov rsi, rdi
    sar rsi, 1
    test rsi, rsi
    jnz .pi_nonzero
    mov byte ptr [rbp-1], 48
    lea rsi, [rbp-1]
    mov rdx, 1
    jmp .pi_write
.pi_nonzero:
    lea rdi, [rbp-1]
    xor ecx, ecx
    mov rax, rsi
    test rax, rax
    jns .pi_pos
    neg rax
    mov cl, 1
.pi_pos:
.pi_loop:
    test rax, rax
    jz .pi_done_digits
    xor edx, edx
    mov r8, 10
    div r8
    add dl, 48
    mov [rdi], dl
    dec rdi
    jmp .pi_loop
.pi_done_digits:
    test cl, cl
    jz .pi_no_sign
    mov byte ptr [rdi], 45
    dec rdi
.pi_no_sign:
    inc rdi
    lea rdx, [rbp-1]
    sub rdx, rdi
    inc rdx
    mov rsi, rdi
.pi_write:
    mov rdi, 1
    mov rax, 1
    syscall
    mov rsp, rbp
    pop rbp
    ret

_nova_print_str:
    push rbp
    mov rbp, rsp
    mov rsi, rdi
    xor edx, edx
.ps_len:
    cmp byte ptr [rsi + rdx], 0
    je .ps_write
    inc edx
    jmp .ps_len
.ps_write:
    mov rdi, 1
    mov rax, 1
    syscall
    mov rsp, rbp
    pop rbp
    ret

_nova_println:
    push rbp
    mov rbp, rsp
    push rdi
    call _nova_print_str
    sub rsp, 8
    mov byte ptr [rsp], 10
    mov rsi, rsp
    mov rdx, 1
    mov rdi, 1
    mov rax, 1
    syscall
    mov rsp, rbp
    pop rbp
    ret

_nova_alloc:
    push rbx
    mov rbx, rdi
    add rbx, 7
    and rbx, -8
    mov rax, [rip + _heap_ptr]
    test rax, rax
    jnz .alloc_have_heap
    xor edi, edi
    mov rax, 12
    syscall
    mov [rip + _heap_base], rax
    mov [rip + _heap_ptr], rax
    lea rdi, [rax + 1048576]
    mov rax, 12
    syscall
    mov [rip + _heap_end], rax
    mov rax, [rip + _heap_ptr]
.alloc_have_heap:
    mov rcx, rax
    add rcx, rbx
    cmp rcx, [rip + _heap_end]
    jbe .alloc_ok
    lea rdi, [rcx + 1048576]
    mov rax, 12
    syscall
    mov [rip + _heap_end], rax
    mov rax, [rip + _heap_ptr]
    mov rcx, rax
    add rcx, rbx
    cmp rcx, [rip + _heap_end]
    jbe .alloc_ok
    mov edi, 1
    mov eax, 60
    syscall
.alloc_ok:
    mov rdx, rcx
    shr rdx, 47
    jnz .alloc_bad_heap
    mov [rip + _heap_ptr], rcx
    pop rbx
    ret
.alloc_bad_heap:
    mov edi, 1
    mov eax, 60
    syscall

_nova_strlen:
    xor eax, eax
    test rdi, rdi
    jz .sl_done
.sl_loop:
    cmp byte ptr [rdi + rax], 0
    je .sl_done
    inc rax
    jmp .sl_loop
.sl_done:
    ret

_nova_concat:
    push rbp
    mov rbp, rsp
    push r12
    push r13
    push r14
    mov r12, rdi
    mov r13, rsi
    call _nova_strlen
    mov r14, rax
    mov rdi, r13
    call _nova_strlen
    add r14, rax
    inc r14
    mov rdi, r14
    call _nova_alloc
    mov r14, rax
    mov rdi, rax
    mov rsi, r12
.cc_copy1:
    lodsb
    test al, al
    jz .cc_copy2
    stosb
    jmp .cc_copy1
.cc_copy2:
    mov rsi, r13
.cc_copy2_loop:
    lodsb
    stosb
    test al, al
    jnz .cc_copy2_loop
    mov rax, r14
    pop r14
    pop r13
    pop r12
    pop rbp
    ret

_nova_int_to_str:
    push rbp
    mov rbp, rsp
    sub rsp, 32
    mov rax, rdi
    sar rax, 1
    lea rsi, [rbp-1]
    mov byte ptr [rsi], 0
    xor ecx, ecx
